code.C:
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>
int cmp(const void *a, const void *b) { return (*(char*)a - *(char*)b); }
int main() {
    char s1[1000], s2[1000];
    if (scanf("%s %s", s1, s2) == 2) {
        int l1 = strlen(s1), l2 = strlen(s2);
        if (l1 != l2) { puts("No"); return 0; }
        for (int i = 0; i < l1; i++) { s1[i] = tolower(s1[i]); s2[i] = tolower(s2[i]); }
        qsort(s1, l1, 1, cmp); qsort(s2, l2, 1, cmp);
        puts(strcmp(s1, s2) == 0 ? "Yes" : "No");
    }
    return 0;
}

code.C++:
#include <iostream>
#include <string>
#include <algorithm>
#include <cctype>
using namespace std;
int main() {
    string s1, s2;
    if (cin >> s1 >> s2) {
        for (char &c : s1) c = tolower(c);
        for (char &c : s2) c = tolower(c);
        sort(s1.begin(), s1.end()); sort(s2.begin(), s2.end());
        cout << (s1 == s2 ? "Yes" : "No") << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
import java.util.Arrays;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            char[] a1 = sc.next().toLowerCase().toCharArray();
            char[] a2 = sc.next().toLowerCase().toCharArray();
            Arrays.sort(a1); Arrays.sort(a2);
            System.out.println(Arrays.equals(a1, a2) ? "Yes" : "No");
        }
    }
}

