const fs = require("fs");
function main() {
    const lines = fs.readFileSync(0, "utf-8").split(/\r?\n/).map(l => l.trim().toLowerCase()).filter(Boolean);
    if (lines.length >= 2) {
        const a1 = lines[0].split("").sort().join("");
        const a2 = lines[1].split("").sort().join("");
        console.log(a1 === a2 ? "Yes" : "No");
    }
}
main();

